-- 0003_data.sql — AUTORITATÍVNA dátová migrácia (reálne dáta z INFOKAT).
-- Nové tabuľky lvs + lv_owners; parcely s formátom kmeň/podlomenie; reálne mená vlastníkov.
CREATE TABLE IF NOT EXISTS lvs (
  id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT NOT NULL, lv_no INTEGER NOT NULL,
  co_owners INTEGER NOT NULL DEFAULT 0, note TEXT);
CREATE TABLE IF NOT EXISTS lv_owners (
  id INTEGER PRIMARY KEY AUTOINCREMENT, dataset_id TEXT NOT NULL, lv_no INTEGER NOT NULL,
  name TEXT NOT NULL, share TEXT, is_company INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_lvs_ds ON lvs(dataset_id);
CREATE INDEX IF NOT EXISTS idx_lvown_ds ON lv_owners(dataset_id, lv_no);
DELETE FROM audit_log;
DELETE FROM import_jobs;
DELETE FROM reports;
DELETE FROM opportunities;
DELETE FROM owners;
DELETE FROM lv_owners;
DELETE FROM lvs;
DELETE FROM parcels;
DELETE FROM datasets;


